def count_intersections(n, points):
    def is_point_on_line(x1, y1, x2, y2, x3, y3):
        # Check if (x3, y3) is on the line defined by (x1, y1) and (x2, y2)
        return (y2 - y1) * (x3 - x1) == (y3 - y1) * (x2 - x1)

    def lines_intersect(p1, p2, p3, p4):
        # Check if lines (p1, p2) and (p3, p4) intersect
        def orientation(x, y, z):
            val = (y[1] - x[1]) * (z[0] - y[0]) - (y[0] - x[0]) * (z[1] - y[1])
            if val == 0:
                return 0
            return 1 if val > 0 else 2

        def on_segment(p, q, r):
            if min(p[0], r[0]) <= q[0] <= max(p[0], r[0]) and min(p[1], r[1]) <= q[1] <= max(p[1], r[1]):
                return True
            return False

        o1 = orientation(p1, p2, p3)
        o2 = orientation(p1, p2, p4)
        o3 = orientation(p3, p4, p1)
        o4 = orientation(p3, p4, p2)

        if o1 != o2 and o3 != o4:
            return True

        if o1 == 0 and on_segment(p1, p3, p2):
            return True
        if o2 == 0 and on_segment(p1, p4, p2):
            return True
        if o3 == 0 and on_segment(p3, p1, p4):
            return True
        if o4 == 0 and on_segment(p3, p2, p4):
            return True

        return False

    count = 0
    for (i, j, k) in combinations(range(n), 3):
        x1, y1 = points[i]
        x2, y2 = points[j]
        x3, y3 = points[k]

        if is_point_on_line(x1, y1, x2, y2, x3, y3):
            continue

        line_segments = [
            (points[i], points[j]),
            (points[i], points[k]),
            (points[j], points[k])
        ]

        for (p1, p2), (p3, p4) in combinations(line_segments, 2):
            if lines_intersect(p1, p2, p3, p4):
                count += 1

    return count

