def count_intersecting_pairs(n, points):
    def normalize(dx, dy):
        if dx == 0 and dy == 0:
            return (0, 0)
        g = gcd(dx, dy)
        return (dx // g, dy // g)

    line_count = {}
    for (x1, y1), (x2, y2) in combinations(points, 2):
        dx, dy = x2 - x1, y2 - y1
        line = normalize(dx, dy)
        if line not in line_count:
            line_count[line] = 0
        line_count[line] += 1

    total_pairs = n * (n - 1) // 2
    intersecting_pairs = 0
    for count in line_count.values():
        intersecting_pairs += count * (count - 1) // 2

    return total_pairs - intersecting_pairs

