def count_intersecting_wires(n, points):
    from itertools import combinations
    from collections import defaultdict
    from math import gcd

    def slope(p1, p2):
        dx, dy = p2[0] - p1[0], p2[1] - p1[1]
        if dx == 0:  # vertical line
            return ('inf', p1[0])
        g = gcd(dx, dy)
        return (dy // g, dx // g)

    def line_key(p1, p2):
        """ Return a normalized key for the line through p1 and p2. """
        m = slope(p1, p2)
        # Normalize the line key so that (1, 2) and (-1, -2) map to the same key
        if m == ('inf', p1[0]):
            return m
        elif m[0] < 0:
            return (-m[0], -m[1])
        else:
            return m

    lines = defaultdict(set)

    # Calculate lines through each pair of points
    for p1, p2 in combinations(points, 2):
        line = line_key(p1, p2)
        lines[line].add(p1)
        lines[line].add(p2)

    intersections = 0

    # Count pairs of lines that share points (and thus intersect)
    for points_on_line in lines.values():
        num_points = len(points_on_line)
        if num_points > 1:
            # Calculate number of intersecting pairs on this line
            intersections += num_points * (num_points - 1) // 2

    return intersections

